#!/bin/bash
# fetch.sh small|medium|large - make the YAML inputs in $INPUTS/yaml.
#   gen/<size>.yaml   generated by gen.py (seed 12345) to 1 MiB / 22.4 MB / 179 MB
#   real/<size>.yaml  real Kubernetes YAML, made by real.sh (REAL=1, or always for small)
# Each input gets <size>.expect.json, PyYAML's canonical text, which every row must write.
set -euo pipefail
source "$(dirname "$0")/../../bin/env.sh"
H=$ROOT/yaml/inputs; D=$INPUTS/yaml/gen; mkdir -p "$D"
case $1 in small) t=1048576 ;; medium) t=22421093 ;; large) t=179368744 ;; esac
if [ ! -f "$D/$1.expect.json" ]; then
  "$PY" "$H/gen.py" $t "$D/$1.yaml"
  "$PY" "$H/prep.py" emit "$D/$1.yaml" "$D/$1.expect.json"
fi
if [ "${REAL:-0}" = 1 ] || [ "$1" = small ]; then "$H/real.sh"; fi
